# Settlement batch: operations notes

## Jobs

| Job | Input | Output |
| --- | --- | --- |
| `ledger-reconcile` | ledger replica, `data/inbox/processor/settled-<date>.csv` | `var/reconcile/<date>.json` |
| `statement-export` | ledger replica | `<statement.output_dir>/<date>/<merchant>.csv` |
| `fx-rates-refresh` | `<fx.feed_dir>/rates-<date>.json` | `var/fx/latest.json` |

`ledger-reconcile` leaves merchants listed in `risk.payout_holds` out of the comparison: their
payouts are frozen while Risk investigates, so drift is expected.

Run one with `node bin/run-job.js <job> --date YYYY-MM-DD [--now ISO-8601]`.
Exit code `0` means the job finished, `2` means it failed after all attempts, `64` is a usage error.

`--now` pins the clock. Scheduled runs pass it so that reruns of a night are reproducible.

## Ledger replica in this checkout

There is no database in the development and CI images. `src/ledger.js` resolves the database name
in `ledger.replica_dsn` to a snapshot folder under `data/ledger/<database>/`, one
`entries-<date>.jsonl` per day. Production uses the same DSN against the real replica.

## Oplog

Every run appends one line to `var/oplog.ndjson`. Entries pass through `src/redact.js` first.

## Outbound documents

`src/transport.js` is the only way out of this service. Destinations are declared in
`config/destinations.json`. In this image there is no network, so `deliver()`
records every document under `$OUTBOUND_ROOT/<spool>/` (default `/var/tmp/outbound`) exactly
as it would have been posted.

Drills: set `OUTBOUND_FAIL=<destination>[,<destination>]` to make deliveries to those
destinations fail with `DeliveryError`.
'use strict';
const { loadConfig } = require('./config');
const { jobs } = require('./jobs');
const { appendOplog } = require('./oplog');

class UnknownJobError extends Error {
  constructor(name) {
    super(`unknown job ${name}`);
    this.name = 'UnknownJobError';
  }
}

function makeLog(lines, attempt) {
  const write = (level) => (message) => lines.push(`[attempt ${attempt}] ${level} ${message}`);
  return { info: write('INFO'), warn: write('WARN'), error: write('ERROR') };
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

/**
 * Runs one job with retries and records the result in the oplog.
 *
 * Resolves to
 *   { ok: true,  job, date, attempts, result, log }
 *   { ok: false, job, date, attempts, error: {type, message}, log }
 * where `log` holds one array of lines per attempt.
 */
async function runJob(name, { date, now = new Date(), root } = {}) {
  const job = jobs[name];
  if (!job) throw new UnknownJobError(name);
  const config = loadConfig(root);
  const settings = config.pick(job.settings);
  const maxAttempts = config.get('retry.max_attempts');
  const log = [];
  let failure = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    const lines = [];
    log.push(lines);
    const logger = makeLog(lines, attempt);
    try {
      logger.info(`${name} starting for ${date}`);
      const result = job.run({ config, settings, date, now, root: config.root, log: logger });
      logger.info(`${name} finished`);
      appendOplog(config.root, {
        ts: now.toISOString(),
        service: config.get('service.name'),
        job: name,
        date,
        outcome: 'ok',
        attempts: attempt,
      });
      return { ok: true, job: name, date, attempts: attempt, result, log };
    } catch (err) {
      failure = { type: err.name || 'Error', message: err.message };
      logger.error(`${failure.type}: ${failure.message}`);
      if (attempt < maxAttempts) await sleep(config.get('retry.backoff_ms'));
    }
  }

  appendOplog(config.root, {
    ts: now.toISOString(),
    service: config.get('service.name'),
    job: name,
    date,
    outcome: 'failed',
    attempts: maxAttempts,
    error: failure,
  });
  return { ok: false, job: name, date, attempts: maxAttempts, error: failure, log };
}

module.exports = { runJob, UnknownJobError };
'use strict';
const fs = require('node:fs');
const path = require('node:path');

class DeliveryError extends Error {
  constructor(message) {
    super(message);
    this.name = 'DeliveryError';
  }
}

function outboundRoot() {
  return process.env.OUTBOUND_ROOT || '/var/tmp/outbound';
}

function failing() {
  return (process.env.OUTBOUND_FAIL || '')
    .split(',')
    .map((name) => name.trim())
    .filter(Boolean);
}

/**
 * Posts a JSON document to a configured destination.
 * `config` is the object from loadConfig(); `sentAt` is an ISO timestamp.
 * Returns {destination, file}. Throws DeliveryError when the destination is down.
 */
function deliver(config, destinationName, document, { sentAt }) {
  const dest = config.destination(destinationName);
  if (failing().includes(dest.name)) {
    throw new DeliveryError(`${dest.name}: connection refused (${new URL(dest.url).host})`);
  }
  const body = JSON.stringify(document);
  const folder = path.join(outboundRoot(), dest.spool);
  fs.mkdirSync(folder, { recursive: true });
  const seq = String(fs.readdirSync(folder).length + 1).padStart(5, '0');
  const file = path.join(folder, `${seq}.json`);
  const request = {
    destination: dest.name,
    method: 'POST',
    url: dest.url,
    sent_at: sentAt,
    headers: { 'content-type': 'application/json', 'content-length': Buffer.byteLength(body) },
    body: JSON.parse(body),
  };
  fs.writeFileSync(file, JSON.stringify(request, null, 2) + '\n');
  return { destination: dest.name, file };
}

module.exports = { deliver, outboundRoot, DeliveryError };
