'use strict';
const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');
const { deliver } = require('./transport');
const { redact, MASK } = require('./redact');

function fingerprint(job, error) {
  const message = error.message.replace(/\d+/g, '#');
  return createHash('sha256').update(`${job}|${error.type}|${message}`).digest('hex').slice(0, 16);
}

/** Project diagnostics for the hosted tracker, not for the local oplog. */
function trackerDiagnostics(config, settings) {
  const accepts = new Set(config.destination('tracker').accepts);
  const replacements = new Map();
  const projections = {};
  const maskLeaves = (value) => {
    if (typeof value === 'string' && value) replacements.set(value, MASK);
    else if (value && typeof value === 'object') Object.values(value).forEach(maskLeaves);
  };

  for (const key of config.keys()) {
    if (accepts.has(config.describe(key).class)) continue;
    const value = config.get(key);
    projections[key] = MASK;
    if (key === 'ledger.replica_dsn') {
      try {
        const url = new URL(value);
        // The endpoint is useful operational context; userinfo and query parameters are not.
        const endpoint = `${url.protocol}//${url.host}${url.pathname}`;
        projections[key] = endpoint;
        replacements.set(value, endpoint);
        if (url.password) {
          replacements.set(url.password, MASK);
          replacements.set(decodeURIComponent(url.password), MASK);
        }
        if (url.username) {
          replacements.set(`user=${decodeURIComponent(url.username)}`, `user=${MASK}`);
        }
      } catch {
        maskLeaves(value);
      }
    } else {
      maskLeaves(value);
    }
  }

  // Longest first prevents partial replacement of an encoded DSN or a nested value.
  const needles = [...replacements.keys()].sort((a, b) => b.length - a.length);
  const pattern = needles.length
    ? new RegExp(needles.map((s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|'), 'g')
    : null;
  const scrub = (value) => {
    if (typeof value === 'string') {
      return pattern ? value.replace(pattern, (match) => replacements.get(match)) : value;
    }
    if (Array.isArray(value)) return value.map(scrub);
    if (value && typeof value === 'object') {
      return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, scrub(item)]));
    }
    return value;
  };
  return {
    settings: Object.fromEntries(Object.entries(settings).map(([key, value]) => [
      key, Object.hasOwn(projections, key) ? projections[key] : value,
    ])),
    sanitize: (value) => scrub(redact(value)),
  };
}

/** Count a terminal failure and return sent, suppressed, or undelivered. */
function reportFailure(config, { job, date, now, attempts, error, log, settings }) {
  const file = path.join(config.root, 'var', 'incidents.json');
  let state;
  try {
    state = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
    state = {};
  }
  const id = fingerprint(job, error);
  const timestamp = now.toISOString();
  const entry = state[id] || { first_seen: timestamp, last_sent: null, occurrences: 0 };
  entry.occurrences += 1;
  state[id] = entry;

  let status = 'suppressed';
  const windowMs = config.get('incident.dedupe_window_minutes') * 60_000;
  if (entry.last_sent === null || now.getTime() - Date.parse(entry.last_sent) >= windowMs) {
    const diagnostics = trackerDiagnostics(config, settings);
    const tailLines = Math.max(0, Math.floor(config.get('incident.log_tail_lines')));
    const document = diagnostics.sanitize({
      title: `${job} failed: ${error.type}`,
      service: config.get('service.name'),
      job,
      run_date: date,
      occurred_at: timestamp,
      fingerprint: id,
      occurrences: entry.occurrences,
      attempts,
      error,
      log_tail: tailLines ? log.at(-1).slice(-tailLines) : [],
      settings: diagnostics.settings,
    });
    try {
      deliver(config, 'tracker', document, { sentAt: timestamp });
      entry.last_sent = timestamp;
      status = 'sent';
    } catch {
      status = 'undelivered';
    }
  }

  fs.mkdirSync(path.dirname(file), { recursive: true });
  const temporary = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(temporary, JSON.stringify(state, null, 2) + '\n');
  fs.renameSync(temporary, file);
  return status;
}

module.exports = { reportFailure };
