'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { createHash } = require('node:crypto');
const { spawnSync } = require('node:child_process');
const { runJob } = require('../src/runner');
const { jobs } = require('../src/jobs');
const { loadConfig } = require('../src/config');
const { reportFailure } = require('../src/reporter');
const { readOplog } = require('../src/oplog');
const { MASK } = require('../src/redact');

const REPO = path.resolve(__dirname, '..');
const NOW = new Date('2026-11-04T09:00:00Z');

function fixture(t, overrides = {}) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'settlement-incident-'));
  for (const dir of ['config', 'data']) {
    fs.cpSync(path.join(REPO, dir), path.join(root, dir), { recursive: true });
  }
  const file = path.join(root, 'config/settings.json');
  const settings = { ...JSON.parse(fs.readFileSync(file, 'utf8')), 'retry.backoff_ms': 0, ...overrides };
  fs.writeFileSync(file, JSON.stringify(settings));
  const env = { OUTBOUND_ROOT: process.env.OUTBOUND_ROOT, OUTBOUND_FAIL: process.env.OUTBOUND_FAIL };
  process.env.OUTBOUND_ROOT = path.join(root, 'outbound');
  delete process.env.OUTBOUND_FAIL;
  t.after(() => {
    for (const [key, value] of Object.entries(env)) {
      if (value === undefined) delete process.env[key];
      else process.env[key] = value;
    }
    fs.rmSync(root, { recursive: true, force: true });
  });
  return root;
}

function requests(root) {
  const dir = path.join(root, 'outbound/tracker');
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).sort().map((file) => JSON.parse(fs.readFileSync(path.join(dir, file), 'utf8')));
}

function state(root) {
  return JSON.parse(fs.readFileSync(path.join(root, 'var/incidents.json'), 'utf8'));
}

function expectedFingerprint(job, error) {
  return createHash('sha256')
    .update(`${job}|${error.type}|${error.message.replace(/\d+/g, '#')}`)
    .digest('hex').slice(0, 16);
}

function fail(root, now = NOW) {
  return runJob('fx-rates-refresh', { root, date: '2026-11-02', now });
}

test('a terminal failure sends one complete document using the run clock and final log tail', async (t) => {
  const root = fixture(t, { 'incident.log_tail_lines': 2, 'service.name': 'settlement-test' });
  const result = await fail(root);
  const [request] = requests(root);
  const id = expectedFingerprint(result.job, result.error);
  assert.equal(request.destination, 'tracker');
  assert.equal(request.url, 'https://api.faultline.example/v2/incidents');
  assert.equal(request.sent_at, NOW.toISOString());
  assert.equal(requests(root).length, 1);
  assert.deepEqual(request.body, {
    title: 'fx-rates-refresh failed: FeedError',
    service: 'settlement-test',
    job: 'fx-rates-refresh',
    run_date: '2026-11-02',
    occurred_at: NOW.toISOString(),
    fingerprint: id,
    occurrences: 1,
    attempts: 3,
    error: result.error,
    log_tail: result.log[2].slice(-2),
    settings: { 'fx.feed_dir': 'data/inbox/fx', 'fx.max_age_hours': 26 },
  });
  assert.deepEqual(state(root), {
    [id]: { first_seen: NOW.toISOString(), last_sent: NOW.toISOString(), occurrences: 1 },
  });
  assert.equal(readOplog(root)[0].incident, 'sent');
});

test('successful jobs do not send, count incidents, or add an incident oplog field', async (t) => {
  const root = fixture(t);
  const result = await runJob('ledger-reconcile', { root, date: '2026-11-02', now: NOW });
  assert.equal(result.ok, true);
  assert.deepEqual(requests(root), []);
  assert.equal(fs.existsSync(path.join(root, 'var/incidents.json')), false);
  assert.equal(Object.hasOwn(readOplog(root)[0], 'incident'), false);
});

test('a job that succeeds on a retry opens nothing', async (t) => {
  const root = fixture(t);
  const job = jobs['ledger-reconcile'];
  const original = job.run;
  let calls = 0;
  t.mock.method(job, 'run', (ctx) => {
    calls += 1;
    if (calls === 1) throw new Error('temporary failure');
    return original(ctx);
  });
  const result = await runJob('ledger-reconcile', { root, date: '2026-11-02', now: NOW });
  assert.equal(result.ok, true);
  assert.equal(result.attempts, 2);
  assert.deepEqual(requests(root), []);
  assert.equal(fs.existsSync(path.join(root, 'var/incidents.json')), false);
  assert.equal(Object.hasOwn(readOplog(root)[0], 'incident'), false);
});

test('de-duplication persists counts, normalizes digits, and expires at the exact boundary', async (t) => {
  const root = fixture(t);
  const first = await fail(root);
  // Different age/count in the message, same normalized fingerprint.
  const second = await fail(root, new Date(NOW.getTime() + 89 * 60_000));
  assert.notEqual(first.error.message, second.error.message);
  assert.equal(requests(root).length, 1);
  const id = expectedFingerprint(first.job, first.error);
  assert.deepEqual(state(root)[id], {
    first_seen: NOW.toISOString(), last_sent: NOW.toISOString(), occurrences: 2,
  });
  const boundary = new Date(NOW.getTime() + 90 * 60_000);
  await fail(root, boundary);
  assert.equal(requests(root).length, 2);
  assert.equal(requests(root)[1].body.occurrences, 3);
  assert.deepEqual(state(root)[id], {
    first_seen: NOW.toISOString(), last_sent: boundary.toISOString(), occurrences: 3,
  });
  assert.deepEqual(readOplog(root).map((entry) => entry.incident), ['sent', 'suppressed', 'sent']);
});

test('fingerprints separate jobs, error types, and non-digit message changes', (t) => {
  const root = fixture(t);
  const config = loadConfig(root);
  const base = {
    job: 'ledger-reconcile', date: '2026-11-03', now: NOW, attempts: 3,
    error: { type: 'TestError', message: 'on 2026-11-03 count 42 amount -1250' },
    log: [['first'], ['second'], ['last']], settings: {},
  };
  assert.equal(reportFailure(config, base), 'sent');
  assert.equal(reportFailure(config, {
    ...base, error: { type: 'TestError', message: 'on 2027-01-15 count 7 amount -200' },
  }), 'suppressed');
  for (const different of [
    { job: 'statement-export' },
    { error: { ...base.error, type: 'OtherError' } },
    { error: { ...base.error, message: 'a different failure 42' } },
  ]) {
    assert.equal(reportFailure(config, { ...base, ...different }), 'sent');
  }
  assert.equal(Object.keys(state(root)).length, 4);
  assert.equal(state(root)[expectedFingerprint(base.job, base.error)].occurrences, 2);
});

test('outages count every failure and recovery immediately sends with the accumulated count', async (t) => {
  const root = fixture(t);
  process.env.OUTBOUND_FAIL = 'tracker';
  const first = await fail(root);
  await fail(root, new Date(NOW.getTime() + 60_000));
  const id = expectedFingerprint(first.job, first.error);
  assert.equal(first.ok, false);
  assert.equal(first.attempts, 3);
  assert.deepEqual(requests(root), []);
  assert.deepEqual(state(root)[id], {
    first_seen: NOW.toISOString(), last_sent: null, occurrences: 2,
  });
  delete process.env.OUTBOUND_FAIL;
  const recoveredAt = new Date(NOW.getTime() + 2 * 60_000);
  await fail(root, recoveredAt);
  assert.equal(requests(root)[0].body.occurrences, 3);
  assert.equal(state(root)[id].last_sent, recoveredAt.toISOString());
  assert.deepEqual(readOplog(root).map((entry) => entry.incident), ['undelivered', 'undelivered', 'sent']);
});

test('an outage after a prior send leaves last_sent unchanged, allowing the next failure to send', async (t) => {
  const root = fixture(t);
  const first = await fail(root);
  const id = expectedFingerprint(first.job, first.error);
  process.env.OUTBOUND_FAIL = 'tracker';
  await fail(root, new Date(NOW.getTime() + 90 * 60_000));
  assert.equal(state(root)[id].last_sent, NOW.toISOString());
  assert.equal(state(root)[id].occurrences, 2);
  delete process.env.OUTBOUND_FAIL;
  await fail(root, new Date(NOW.getTime() + 91 * 60_000));
  assert.equal(requests(root).length, 2);
  assert.equal(requests(root)[1].body.occurrences, 3);
  assert.deepEqual(readOplog(root).map((entry) => entry.incident), ['sent', 'undelivered', 'sent']);
});

test('a zero log-tail setting sends no lines', async (t) => {
  const root = fixture(t, { 'incident.log_tail_lines': 0 });
  await fail(root);
  assert.deepEqual(requests(root)[0].body.log_tail, []);
});

test('reconciliation includes tuning and replica identity, but no restricted Risk notes or credentials', async (t) => {
  const root = fixture(t);
  const result = await runJob('ledger-reconcile', { root, date: '2026-11-03', now: NOW });
  const body = requests(root)[0].body;
  assert.deepEqual(body.settings, {
    'ledger.replica_dsn': 'postgresql://ledger-replica.int.corvidpay.example:5432/ledger',
    'ledger.timeout_ms': 8000,
    'reconcile.batch_size': 4,
    'reconcile.tolerance_minor': 5,
    'risk.payout_holds': MASK,
  });
  const config = loadConfig(root);
  const note = Object.values(config.get('risk.payout_holds'))[0];
  assert.ok(result.log[2].some((line) => line.includes(note)));
  const serialized = JSON.stringify(requests(root));
  assert.equal(serialized.includes(note), false);
  assert.equal(serialized.includes('RSK-2291'), false);
  const url = new URL(config.get('ledger.replica_dsn'));
  assert.equal(serialized.includes(url.password), false);
  assert.equal(serialized.includes(decodeURIComponent(url.password)), false);
});

test('missing snapshot conninfo is safe in outbound logs without changing the job log', async (t) => {
  const root = fixture(t);
  const result = await runJob('statement-export', { root, date: '2026-11-05', now: NOW });
  const password = decodeURIComponent(new URL(loadConfig(root).get('ledger.replica_dsn')).password);
  assert.ok(result.log[2].some((line) => line.includes(password)));
  const request = requests(root)[0];
  assert.equal(JSON.stringify(request).includes(password), false);
  assert.ok(request.body.log_tail.some((line) => line.includes(`password=${MASK}`)));
  assert.ok(request.body.log_tail.some((line) => line.includes('host=ledger-replica.int.corvidpay.example')));
});

test('new restricted settings are masked by schema class, including nested log values', (t) => {
  const root = fixture(t);
  const dir = path.join(root, 'config');
  const schema = JSON.parse(fs.readFileSync(path.join(dir, 'schema.json'), 'utf8'));
  const settings = JSON.parse(fs.readFileSync(path.join(dir, 'settings.json'), 'utf8'));
  schema.keys['new.private_notes'] = { type: 'object', class: 'restricted' };
  settings['new.private_notes'] = { nested: ['restricted-detail-unique'] };
  fs.writeFileSync(path.join(dir, 'schema.json'), JSON.stringify(schema));
  fs.writeFileSync(path.join(dir, 'settings.json'), JSON.stringify(settings));
  const config = loadConfig(root);
  reportFailure(config, {
    job: 'test', date: '2026-11-04', now: NOW, attempts: 1,
    error: { type: 'Error', message: 'restricted-detail-unique' },
    log: [['restricted-detail-unique']], settings: config.pick(['new.private_notes']),
  });
  const body = requests(root)[0].body;
  assert.equal(body.settings['new.private_notes'], MASK);
  assert.equal(body.error.message, MASK);
  assert.deepEqual(body.log_tail, [MASK]);
});

test('CLI keeps failure code 2 and oplog during tracker outages, success 0, usage 64', (t) => {
  const root = fixture(t);
  const cli = (...args) => spawnSync(process.execPath, [path.join(REPO, 'bin/run-job.js'), ...args], {
    env: { ...process.env, APP_ROOT: root, OUTBOUND_FAIL: 'tracker' }, encoding: 'utf8',
  });
  const failed = cli('ledger-reconcile', '--date', '2026-11-03', '--now', NOW.toISOString());
  assert.equal(failed.status, 2, failed.stderr);
  assert.match(failed.stderr, /failed after 3 attempt\(s\): ReconcileMismatchError/);
  assert.equal(readOplog(root)[0].incident, 'undelivered');
  assert.equal(Object.values(state(root))[0].occurrences, 1);
  assert.equal(cli('ledger-reconcile', '--date', '2026-11-02').status, 0);
  assert.equal(cli('not-a-job', '--date', '2026-11-02').status, 64);
  assert.equal(cli().status, 64);
  assert.equal(readOplog(root).length, 2);
});
